@pytest.mark.parametrize('invalid', ['missing_ref', 'old_basis']) def test_requirement_edit_preserves_unusable_refs_and_basis_until_reselect(workbench, invalid): import copy from deck_master import ui_journal page, context, store, url, _, _ = workbench state = persisted_requirement(workbench) record = next(r for r in ui_journal.list_drafts(store.project_root)['records'] if r['draft']['content'].get('requirement') == state) draft = copy.deepcopy(record['draft']) if invalid == 'missing_ref': draft['content']['requirement']['annotation_refs'][0]['sha256'] = '0' * 64 else: draft['content']['requirement']['basis']['revision_id'] = store.read_object_json( store.load_document()['annotations'][0])['base_revision'] ui_journal.save(store.project_root, draft=draft, expected_etag=record['etag']) original = copy.deepcopy(draft['content']['requirement']) other = isolated_context(workbench) try: test_page = other.new_page() test_page.goto(url + '#' + page.url.split('#')[1]) expect(test_page.locator('.requirement-ref')).to_have_count(0) expect(test_page.locator('.change-requirement')).to_contain_text('请重新选择') text = '只改文字，保留原来的引用证据' test_page.get_by_label('修改要求', exact=True).fill(text) stored = saved_requirement(test_page, text) assert stored['annotation_refs'] == original['annotation_refs'] assert stored['basis'] == original['basis'] test_page.reload() expect(test_page.get_by_role('button', name='预览修改影响', exact=True)).to_be_disabled() test_page.get_by_label('选入意见 1', exact=True).check() expect(test_page.get_by_role('button', name='预览修改影响', exact=True)).to_be_enabled() test_page.get_by_role('button', name='预览修改影响', exact=True).click() > expect(test_page.get_by_role('button', name='确认计划并创建交接', exact=True)).to_be_visible() E AssertionError: Locator expected to be visible E Actual value: None E Error: element(s) not found E Call log: E - Expect "to_be_visible" get_by_role("button", name="确认计划并创建交接", exact=True) with timeout 5000ms E - waiting for get_by_role("button", name="确认计划并创建交接"